package main

import (
	"bufio"
	"fmt"
	"os"
)

type ModInt uint32

const MOD uint32 = 1000000007

func NewModInt(x uint32) ModInt {
	return ModInt(x % MOD)
}

func (a ModInt) Add(b ModInt) ModInt {
	x := uint32(a) + uint32(b)
	if x >= MOD {
		x -= MOD
	}
	return ModInt(x)
}

func (a ModInt) Sub(b ModInt) ModInt {
	x := MOD + uint32(a) - uint32(b)
	if x >= MOD {
		x -= MOD
	}
	return ModInt(x)
}

func (a ModInt) Mul(b ModInt) ModInt {
	x := (uint64(a) * uint64(b)) % uint64(MOD)
	return ModInt(uint32(x))
}

func (a ModInt) Pow(n uint64) ModInt {
	res := ModInt(1)
	base := a
	for n > 0 {
		if n&1 == 1 {
			res = res.Mul(base)
		}
		base = base.Mul(base)
		n >>= 1
	}
	return res
}

func (a ModInt) Inv() ModInt {
	return a.Pow(uint64(MOD - 2))
}

func ModIntZero() ModInt {
	return ModInt(0)
}

func ModIntOne() ModInt {
	return ModInt(1)
}

type SquareMatrix struct {
	size int
	buf  []ModInt
}

func NewSquareMatrixZero(size int) SquareMatrix {
	buf := make([]ModInt, size*size)
	return SquareMatrix{size: size, buf: buf}
}

func NewSquareMatrixIdentity(size int) SquareMatrix {
	m := NewSquareMatrixZero(size)
	for i := 0; i < size; i++ {
		m.buf[i*size+i] = ModIntOne()
	}
	return m
}

func (m *SquareMatrix) Get(x, y int) ModInt {
	return m.buf[x*m.size+y]
}

func (m *SquareMatrix) GetMut(x, y int) *ModInt {
	return &m.buf[x*m.size+y]
}

func (m *SquareMatrix) MatAdd(rhs *SquareMatrix) SquareMatrix {
	size := m.size
	buf := make([]ModInt, size*size)
	for i := 0; i < size*size; i++ {
		buf[i] = m.buf[i].Add(rhs.buf[i])
	}
	return SquareMatrix{size: size, buf: buf}
}

func (m *SquareMatrix) MatSub(rhs *SquareMatrix) SquareMatrix {
	size := m.size
	buf := make([]ModInt, size*size)
	for i := 0; i < size*size; i++ {
		buf[i] = m.buf[i].Sub(rhs.buf[i])
	}
	return SquareMatrix{size: size, buf: buf}
}

func (m *SquareMatrix) MatMul(rhs *SquareMatrix) SquareMatrix {
	size := m.size
	res := NewSquareMatrixZero(size)
	for i := 0; i < size; i++ {
		rowRes := res.buf[i*size : (i+1)*size]
		rowA := m.buf[i*size : (i+1)*size]
		for k := 0; k < size; k++ {
			a := rowA[k]
			colB := rhs.buf[k*size : (k+1)*size]
			for j := 0; j < size; j++ {
				rowRes[j] = rowRes[j].Add(a.Mul(colB[j]))
			}
		}
	}
	return res
}

func (m *SquareMatrix) MatPow(n uint64) SquareMatrix {
	size := m.size
	res := NewSquareMatrixIdentity(size)
	base := *m
	for n > 0 {
		if n&1 == 1 {
			tmp := res.MatMul(&base)
			res = tmp
		}
		tmp := base.MatMul(&base)
		base = tmp
		n >>= 1
	}
	return res
}

type Precalc struct {
	inv   []ModInt
	fact  []ModInt
	ifact []ModInt
}

func NewPrecalc(n int) Precalc {
	inv := make([]ModInt, n+1)
	fact := make([]ModInt, n+1)
	ifact := make([]ModInt, n+1)
	for i := 0; i <= n; i++ {
		inv[i] = ModIntOne()
		fact[i] = ModIntOne()
		ifact[i] = ModIntOne()
	}
	for i := 2; i <= n; i++ {
		fact[i] = fact[i-1].Mul(NewModInt(uint32(i)))
	}
	ifact[n] = fact[n].Inv()
	if n > 0 {
		inv[n] = ifact[n].Mul(fact[n-1])
	}
	for i := n - 1; i >= 1; i-- {
		ifact[i] = ifact[i+1].Mul(NewModInt(uint32(i + 1)))
		inv[i] = ifact[i].Mul(fact[i-1])
	}
	return Precalc{inv: inv, fact: fact, ifact: ifact}
}

func (p *Precalc) Inv(n int) ModInt {
	return p.inv[n]
}

func (p *Precalc) Fact(n int) ModInt {
	return p.fact[n]
}

func (p *Precalc) IFact(n int) ModInt {
	return p.ifact[n]
}

func (p *Precalc) Perm(n, k int) ModInt {
	if k > n {
		return ModIntZero()
	}
	return p.fact[n].Mul(p.ifact[n-k])
}

func (p *Precalc) Comb(n, k int) ModInt {
	if k > n {
		return ModIntZero()
	}
	return p.fact[n].Mul(p.ifact[k]).Mul(p.ifact[n-k])
}

func mulMatVec(m *SquareMatrix, b []ModInt) []ModInt {
	n := len(b)
	res := make([]ModInt, n)
	for i := 0; i < n; i++ {
		sum := ModIntZero()
		for j := 0; j < n; j++ {
			sum = sum.Add(m.Get(i, j).Mul(b[j]))
		}
		res[i] = sum
	}
	return res
}

func run() {
	in := bufio.NewReader(os.Stdin)
	w := make([]int, 7)
	for i := 0; i < 7; i++ {
		fmt.Fscan(in, &w[i])
	}

	var mats []SquareMatrix
	for i := 1; i <= 7; i++ {
		size := 1 << i
		m := NewSquareMatrixZero(size)
		for j := 0; j < (1 << i); j++ {
			for k := 0; k < (1 << (2*i - 1)); k++ {
				if (j & k) > 0 {
					continue
				}
				next := 0
				for x := 0; x < i; x++ {
					left := x == 0 || ((k>>(i+x-1))&1) == 1
					down := ((k >> x) & 1) == 1
					right := x == i-1 || ((k>>(i+x))&1) == 1
					if left && down && right {
						next |= 1 << x
					}
				}
				v := m.GetMut(next, j)
				*v = v.Add(ModIntOne())
			}
		}
		mats = append(mats, m)
		m2 := NewSquareMatrixZero(size)
		for j := 0; j < size; j++ {
			*m2.GetMut(j, j) = ModIntOne()
		}
		mats = append(mats, m2)
	}

	b := make([]ModInt, 1<<7)
	ini := false
	for idx := 6; idx >= 0; idx-- {
		i := idx
		wv := &w[i]
		matPair := mats[2*i : 2*i+2]
		if !ini && *wv > 0 {
			*wv--
			ini = true
			ii := i + 1
			for k := 0; k < (1 << (ii - 1)); k++ {
				bit := 0
				for x := 0; x < ii; x++ {
					left := x == 0 || ((k>>(x-1))&1) == 1
					down := true
					right := x == ii-1 || ((k>>x)&1) == 1
					if left && right && down {
						bit |= 1 << x
					}
				}
				b[bit] = b[bit].Add(ModIntOne())
			}
		}
		b = mulMatVec(&matPair[1], b)
		powMat := matPair[0].MatPow(uint64(*wv))
		b = mulMatVec(&powMat, b)
		b = b[:1<<uint(i+1)]
	}

	ans := b[0]
	fmt.Println(uint32(ans))
}

func main() {
	run()
}

