func (m *SquareMatrix) MatMul(rhs *SquareMatrix) SquareMatrix {
	if m.size != rhs.size {
		panic("size mismatch")
	}
	size := m.size
	res := NewSquareMatrixZero(size)
	for row := 0; row < size; row++ {
		for colBlock := 0; colBlock < size; colBlock++ {
			a := m.buf[row*size+colBlock]
			for col := 0; col < size; col++ {
				x := &res.buf[row*size+col]
				*x = x.Add(a.Mul(rhs.buf[colBlock*size+col]))
			}
		}
	}
	return res
