	size := m.size
	t := NewSquareMatrixIdentity(size)
	s := *m
	for n > 0 {
		if n&1 == 1 {
			tmp := t.MatMul(&s)
			t = tmp
		}
		tmp := s.MatMul(&s)
		s = tmp
		n >>= 1
	}
	return t
