type Precalc struct {
	inv   []ModInt
	fact  []ModInt
	ifact []ModInt
}

func NewPrecalc(n int) *Precalc {
	inv := make([]ModInt, n+1)
	fact := make([]ModInt, n+1)
	ifact := make([]ModInt, n+1)
	for i := 0; i <= n; i++ {
		inv[i] = ModIntOne()
		fact[i] = ModIntOne()
		ifact[i] = ModIntOne()
	}
	for i := 2; i <= n; i++ {
		fact[i] = fact[i-1].Mul(NewModIntUnchecked(uint32(i)))
	}
	ifact[n] = fact[n].Inv()
	if n > 0 {
		inv[n] = ifact[n].Mul(fact[n-1])
	}
	for i := n - 1; i >= 1; i-- {
		ifact[i] = ifact[i+1].Mul(NewModIntUnchecked(uint32(i + 1)))
		inv[i] = ifact[i].Mul(fact[i-1])
	}
	return &Precalc{inv: inv, fact: fact, ifact: ifact}
}

func (p *Precalc) Inv(n int) ModInt {
	if n <= 0 {
		panic("inv: n must be > 0")
	}
	return p.inv[n]
}

